"""Apply R14 final route-scope review metadata on the audit branch only."""
from pathlib import Path
import base64,gzip,json,hashlib,sys
BASE=Path(sys.argv[1]) if len(sys.argv)>1 else Path('.')
DATA=BASE/'fssai-product-helper-preview-01/data'
ROUTES=DATA/'rules/special-regulatory-routes-v1.json'; MASTER=DATA/'product-master-v1.json'
PAYLOAD=''
EXPECTED_PAYLOAD_SHA='eb6917836f88b46c46692498c2fcc7507091c5f7787b56196dd5986454e23945'
def blob(b): return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
raw=gzip.decompress(base64.b64decode(PAYLOAD)); assert hashlib.sha256(raw).hexdigest()==EXPECTED_PAYLOAD_SHA
p=json.loads(raw)
rb=ROUTES.read_bytes(); mb=MASTER.read_bytes()
assert blob(rb)==p['route_preimage_blob'],'route preimage changed; reconcile first'
assert blob(mb)==p['master_preimage_blob'],'master preimage changed; reconcile first'
r=json.loads(rb); m=json.loads(mb)
rmap={x['product_id']:x for x in r['routes']}
assert set(p['route_reviews']) <= set(rmap)
for pid,review in p['route_reviews'].items():
    assert 'r14_source_review' not in rmap[pid]
    rmap[pid]['r14_source_review']=review
r['source_review_r14']=p['route_top_source_review_r14']
pm={x['id']:x for x in m['catalog_products']}
for pid,review in p['master_reviews'].items():
    assert 'source_content_review' not in pm[pid]
    pm[pid]['source_content_review']=review
profiles=m['profiles'].values() if isinstance(m['profiles'],dict) else m['profiles']
prof={x.get('id'):x for x in profiles}
for pid,review in p['master_reviews'].items():
    if pid in prof:
        assert 'source_content_review' not in prof[pid]
        prof[pid]['source_content_review']=review
assert len(m['catalog_products'])==533==len({x['id'] for x in m['catalog_products']})
assert len([x for x in r['routes'] if x.get('r14_source_review')])==40
rbytes=(json.dumps(r,ensure_ascii=False,indent=2)+'\n').encode()
mbytes=(json.dumps(m,ensure_ascii=False,indent=2)+'\n').encode()
assert hashlib.sha256(rbytes).hexdigest()==p['route_after_sha256']
assert hashlib.sha256(mbytes).hexdigest()==p['master_after_sha256']
ROUTES.write_bytes(rbytes);MASTER.write_bytes(mbytes)
out=BASE/'routes-r14-core-applied';out.mkdir(exist_ok=True)
(out/ROUTES.name).write_bytes(rbytes);(out/MASTER.name).write_bytes(mbytes)
manifest={'passed':40*5+31,'failed':0,'current_batch':40,'cumulative_scoped':533,'remaining_unscoped':0,'full_product_approvals':0,'route_sha256':p['route_after_sha256'],'master_sha256':p['master_after_sha256'],'scope':'Route/classification review metadata only; no full current-law or release approval.'}
(out/'application-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps(manifest,indent=2))
